contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint deposit, uint am) public payable {
        require(deposit > 0);
        require(am > 0);
        require(am <= deposit);
        require(address(this).balance >= deposit);
        c.SetMinSum(0);
        c.Deposit{value: deposit}();
        uint beforeBal = c.balances(address(this));
        uint beforeC = address(c).balance;
        c.Collect(am);
        assert(
            c.balances(address(this)) == beforeBal - am &&
            address(c).balance == beforeC - am &&
            address(this).balance >= am
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint v, uint v2) public {
        // Before initialization, SetMinSum(v) must succeed and take effect.
        c.SetMinSum(v);
        uint msAfter = c.MinSum();

        // Initialize the contract.
        c.Initialized();

        // After initialization, SetMinSum must revert.
        bool reverted;
        try c.SetMinSum(v2) { reverted = false; } catch { reverted = true; }

        uint msFinal = c.MinSum();
        assert(reverted && msAfter == v && msFinal == msAfter);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _am) public {
        // Fresh deployment: this contract's recorded balance is below MinSum (default 1 ether),
        // so the Collect conditions cannot hold.
        uint balBefore = c.balances(address(this));
        uint ethBefore = address(c).balance;
        uint minSumBefore = c.MinSum();

        require(balBefore < minSumBefore);

        bool reverted;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }

        uint balAfter = c.balances(address(this));
        uint ethAfter = address(c).balance;

        assert(!reverted && balAfter == balBefore && ethAfter == ethBefore);
    }

    receive() external payable {}
}

