contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // This contract has NO payable receive/fallback, so a low-level call
    // sending it Ether will fail, making Collect revert.

    function run(uint _am, uint amount) public {
        require(amount > 0);
        require(address(this).balance >= amount);
        c.Deposit{value: amount}();
        c.Initialized();
        c.SetMinSum(0);
        uint256 balBefore = c.balances(address(this));
        require(balBefore >= _am);
        uint contractBalBefore = address(c).balance;
        bool reverted;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }
        assert(reverted && c.balances(address(this)) == balBefore && address(c).balance == contractBalBefore);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _v1, uint _v2) public {
        // Before initialization, SetMinSum freely updates MinSum.
        c.SetMinSum(_v1);
        uint minBefore = c.MinSum();
        c.Initialized();
        // After initialization, SetMinSum must revert and leave MinSum unchanged.
        bool reverted;
        try c.SetMinSum(_v2) { reverted = false; } catch { reverted = true; }
        assert(reverted && minBefore == _v1 && c.MinSum() == _v1);
    }
}

