contract InvMutTest {
    C c;
    uint256 observedDuringTransfer;
    bool observed;

    constructor(C _c) { c = _c; }

    function run(uint256 depositAmount, uint256 am) public payable {
        require(address(this).balance >= depositAmount);
        c.Deposit{value: depositAmount}();
        uint256 b0 = c.balances(address(this));
        require(b0 >= 1 ether);
        require(am > 0 && am <= b0);
        observed = false;
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
        uint256 b1 = c.balances(address(this));
        assert(!reverted && observed && observedDuringTransfer == b0 - am && b1 == b0 - am);
    }

    receive() external payable {
        observedDuringTransfer = c.balances(address(this));
        observed = true;
    }
}

contract InvMutTest {
    C c;
    uint constant MAGIC = 777;
    constructor(C _c) { c = _c; }
    function run(uint deposit, uint amount) public payable {
        require(deposit > 0 && amount > 0 && amount <= deposit);
        c.SetMinSum(0);
        c.Deposit{value: deposit}();
        uint balBefore = c.balances(address(this));
        uint cBalBefore = address(c).balance;
        bool reverted;
        if (amount == MAGIC) {
            try c.Collect(amount) { reverted = false; } catch { reverted = true; }
        } else {
            c.Collect(amount);
            reverted = false;
        }
        uint balAfter = c.balances(address(this));
        uint cBalAfter = address(c).balance;
        if (reverted) {
            assert(balAfter == balBefore && cBalAfter == cBalBefore);
        } else {
            assert(balAfter == balBefore - amount && cBalAfter == cBalBefore - amount);
        }
    }
    receive() external payable {
        if (msg.value == MAGIC) { revert(); }
    }
}

